INSERT IGNORE INTO products (id, name, slug, short_description, description, thumbnail_url, base_price, status, product_type, is_featured, average_rating, total_reviews, total_sold, brand_id, created_by, updated_by, is_deleted) VALUES
(1, 'Sữa Rửa Mặt CeraVe Foaming Facial Cleanser', 'sua-rua-mat-cerave-foaming-facial-cleanser', 'Sữa rửa mặt phát triển bởi bác sĩ da liễu giúp làm sạch sâu mà không phục hồi màng bảo vệ da.', 'Sữa rửa mặt phát triển bởi bác sĩ da liễu giúp làm sạch sâu mà không phục hồi màng bảo vệ da.', 'https://img.com/cerave-cleanser.jpg', 190000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 3, 'system', 'system', FALSE),
(2, 'Gel Rửa Mặt La Roche-Posay Effaclar Purifying Foaming Gel', 'gel-rua-mat-la-roche-posay-effaclar-purifying-foaming-gel', 'Sữa rửa mặt dạng gel giúp kiềm dầu và giảm mụn hiệu quả cho da dầu nhạy cảm.', 'Sữa rửa mặt dạng gel giúp kiềm dầu và giảm mụn hiệu quả cho da dầu nhạy cảm.', 'https://img.com/laroche-effaclar.jpg', 185000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 4, 'system', 'system', FALSE),
(3, 'Nước Tẩy Trang Bioderma Sensibio H2O Micellar Water', 'nuoc-tay-trang-bioderma-sensibio-h2o-micellar-water', 'Nước tẩy trang công nghệ Micellar làm sạch sâu lớp trang điểm và bụi mịn.', 'Nước tẩy trang công nghệ Micellar làm sạch sâu lớp trang điểm và bụi mịn.', 'https://img.com/bioderma-h2o.jpg', 150000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 5, 'system', 'system', FALSE),
(4, 'Nước Cân Bằng Anua Heartleaf 77% Soothing Toner', 'nuoc-can-bang-anua-heartleaf-77-soothing-toner', 'Nước hoa hồng chiết xuất diếp cá giúp làm dịu da mụn và cấp ẩm tức thì.', 'Nước hoa hồng chiết xuất diếp cá giúp làm dịu da mụn và cấp ẩm tức thì.', 'https://img.com/anua-heartleaf.jpg', 320000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 12, 'system', 'system', FALSE),
(5, 'Dưỡng Chất Khoáng Cô Đặc Vichy Mineral 89 Booster', 'duong-chat-khoang-co-dac-vichy-mineral-89-booster', 'Tinh chất dưỡng ẩm chuyên sâu với 89% nước khoáng núi lửa Vichy.', 'Tinh chất dưỡng ẩm chuyên sâu với 89% nước khoáng núi lửa Vichy.', 'https://img.com/vichy-m89.jpg', 520000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 6, 'system', 'system', FALSE),
(6, 'Kem Dưỡng Ẩm CeraVe Moisturizing Cream', 'kem-duong-am-cerave-moisturizing-cream', 'Kem dưỡng ẩm chuyên sâu giúp phục hồi hàng rào bảo vệ da dành cho da khô.', 'Kem dưỡng ẩm chuyên sâu giúp phục hồi hàng rào bảo vệ da dành cho da khô.', 'https://img.com/cerave-cream.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 3, 'system', 'system', FALSE),
(7, 'Kem Chống Nắng La Roche-Posay Anthelios UVMune 400', 'kem-chong-nang-la-roche-posay-anthelios-uvmune-400', 'Kem chống nắng kiểm dầu bọt mịn, bảo vệ da tối đa trước tia UV.', 'Kem chống nắng kiểm dầu bọt mịn, bảo vệ da tối đa trước tia UV.', 'https://img.com/laroche-anthelios.jpg', 495000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 4, 'system', 'system', FALSE),
(8, 'Mặt Nạ Đất Sét Innisfree Super Volcanic Pore Clay Mask', 'mat-na-dat-set-innisfree-super-volcanic-pore-clay-mask', 'Mặt nạ đất sét giảm mụn đầu đen và se khít lỗ chân lông.', 'Mặt nạ đất sét giảm mụn đầu đen và se khít lỗ chân lông.', 'https://img.com/innisfree-clay.jpg', 25000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 16, 'system', 'system', FALSE),
(9, 'Nước Hoa Hồng Tẩy Tế Bào Chết COSRX BHA Blackhead Power Liquid', 'nuoc-hoa-hong-tay-te-bao-chet-cosrx-bha-blackhead-power-liquid', 'Tẩy tế bào chết hóa học chứa 2% BHA giúp làm sạch sâu lỗ chân lông.', 'Tẩy tế bào chết hóa học chứa 2% BHA giúp làm sạch sâu lỗ chân lông.', 'https://img.com/cosrx-bha.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 13, 'system', 'system', FALSE),
(10, 'Xịt Khoáng Avène Thermal Spring Water', 'xit-khoang-avene-thermal-spring-water', 'Xịt khoáng làm dịu da và chống oxy hóa từ nguồn khoáng tinh khiết.', 'Xịt khoáng làm dịu da và chống oxy hóa từ nguồn khoáng tinh khiết.', 'https://img.com/avene-thermal.jpg', 170000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 8, 'system', 'system', FALSE),
(11, 'Son Thỏi 3CE Blur Matte Lipstick', 'son-thoi-3ce-blur-matte-lipstick', 'Son thỏi lì hiệu ứng mờ mịn môi thời thượng.', 'Son thỏi lì hiệu ứng mờ mịn môi thời thượng.', 'https://img.com/3ce-matte.jpg', 369000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 26, 'system', 'system', FALSE),
(12, 'Son Kem Lì Maybelline SuperStay Matte Ink', 'son-kem-li-maybelline-superstay-matte-ink', 'Son kem lì nhẹ môi, giữ màu lâu trôi suốt 16 tiếng.', 'Son kem lì nhẹ môi, giữ màu lâu trôi suốt 16 tiếng.', 'https://img.com/maybelline-ink.jpg', 249000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 2, 'system', 'system', FALSE),
(13, 'Kem Nền Maybelline Fit Me Matte + Poreless Foundation', 'kem-nen-maybelline-fit-me-matte-poreless-foundation', 'Kem nền che phủ hoàn hảo, kiềm dầu tối ưu cho lớp nền mịn lì.', 'Kem nền che phủ hoàn hảo, kiềm dầu tối ưu cho lớp nền mịn lì.', 'https://img.com/maybelline-fitme.jpg', 279000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 2, 'system', 'system', FALSE),
(14, 'Phấn Phủ Bột Kiềm Dầu Innisfree No-Sebum Mineral Powder', 'phan-phu-bot-kiem-dau-innisfree-no-sebum-mineral-powder', 'Phấn phủ dạng bột khoáng kiềm dầu, trong suốt tự nhiên.', 'Phấn phủ dạng bột khoáng kiềm dầu, trong suốt tự nhiên.', 'https://img.com/innisfree-powder.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 16, 'system', 'system', FALSE),
(15, 'Mascara Maybelline Lash Sensational Sky High', 'mascara-maybelline-lash-sensational-sky-high', 'Mascara làm dài và cong mi tối đa, không lem không trôi.', 'Mascara làm dài và cong mi tối đa, không lem không trôi.', 'https://img.com/maybelline-skyhigh.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 2, 'system', 'system', FALSE),
(16, 'Bút Kẻ Mắt Nước Maybelline Hyper Sharp Liner', 'but-ke-mat-nuoc-maybelline-hyper-sharp-liner', 'Bút kẻ mắt nước nét mảnh, chống thấm nước tuyệt đối.', 'Bút kẻ mắt nước nét mảnh, chống thấm nước tuyệt đối.', 'https://img.com/maybelline-liner.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 2, 'system', 'system', FALSE),
(17, 'Chì Kẻ Mày 2 Đầu Innisfree Auto Eyebrow Pencil', 'chi-ke-may-2-dau-innisfree-auto-eyebrow-pencil', 'Chì kẻ mày thiết kế 2 đầu tiện lợi, lâu trôi.', 'Chì kẻ mày thiết kế 2 đầu tiện lợi, lâu trôi.', 'https://img.com/innisfree-brow.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 16, 'system', 'system', FALSE),
(18, 'Dầu Gội Tresemmé Keratin Smooth Vào Nếp Mượt Mà', 'dau-goi-tresemme-keratin-smooth-vao-nep-muot-ma', 'Dầu gội phục hồi tóc hư tổn từ sâu bên trong.', 'Dầu gội phục hồi tóc hư tổn từ sâu bên trong.', 'https://img.com/tresemme-keratin.jpg', 100000.00, 'ACTIVE', 'PRODUCT', FALSE, 5.0, 0, 0, 38, 'system', 'system', FALSE),
